CREATE OR REPLACE PROCEDURE sp(para_eer_threshold real, para_target_mode text)
LANGUAGE plpgsql
AS $$
DECLARE
    next_id bigint;
    r record;
    v_original_power_watts numeric;
    v_working_rated_capacity numeric;
    v_capacity_ratio numeric;
    v_actual_efficiency numeric;
    v_actual_cop numeric;
    v_total_consumption numeric;
    v_sample_days integer;
    v_avg_indoor numeric;
    v_avg_outdoor numeric;
    v_avg_setting numeric;
    v_setpoint_flag boolean;
    v_carnot_cop numeric;
    v_annual_emissions numeric;
    v_energy_multiplier numeric;
BEGIN
    DELETE FROM carbon_emissions WHERE annual_emissions_tonnes <= 0;

    SELECT COALESCE(MAX(id), 0) + 1 INTO next_id FROM carbon_emissions;

    FOR r IN
        SELECT a.ac_id,
               a.manufacturer,
               a.model,
               a.cooling_capacity_btu,
               a.heating_capacity_btu,
               a.power_consumption_watts,
               a.energy_efficiency_ratio,
               a.refrigerant_type,
               rp.phase_change_heat_kj_per_kg,
               rp.refrigerant_flow_rate_kg_per_s
        FROM air_conditioner_info a
        LEFT JOIN refrigerant_properties rp
               ON a.refrigerant_type = rp.refrigerant_type
        ORDER BY a.ac_id ASC
    LOOP
        v_original_power_watts := r.power_consumption_watts;

        IF para_target_mode = 'Heating' THEN
            v_working_rated_capacity := r.heating_capacity_btu;
        ELSE
            v_working_rated_capacity := r.cooling_capacity_btu;
        END IF;

        IF r.phase_change_heat_kj_per_kg IS NOT NULL
           AND r.refrigerant_flow_rate_kg_per_s IS NOT NULL THEN
            IF v_working_rated_capacity = 0 THEN
                v_capacity_ratio := NULL;
            ELSE
                v_capacity_ratio :=
                    (r.phase_change_heat_kj_per_kg
                     * r.refrigerant_flow_rate_kg_per_s
                     * 3412.14)
                    / v_working_rated_capacity;
            END IF;

            IF r.power_consumption_watts = 0 THEN
                v_actual_efficiency := NULL;
            ELSE
                v_actual_efficiency :=
                    v_working_rated_capacity / r.power_consumption_watts;
            END IF;
        ELSE
            v_capacity_ratio := 1.0;
            v_actual_efficiency := r.energy_efficiency_ratio;
        END IF;

        IF v_actual_efficiency IS NULL THEN
            v_actual_cop := NULL;
        ELSE
            v_actual_cop := v_actual_efficiency / 3.412;
        END IF;

        SELECT COALESCE(SUM(energy_consumption_kwh), 0),
               COUNT(DISTINCT record_date)::integer,
               AVG(indoor_temperature_celsius),
               AVG(outdoor_temperature_celsius),
               AVG(temperature_setting_celsius)
          INTO v_total_consumption,
               v_sample_days,
               v_avg_indoor,
               v_avg_outdoor,
               v_avg_setting
          FROM energy_consumption
         WHERE ac_id = r.ac_id
           AND mode = para_target_mode;

        v_setpoint_flag := false;
        IF v_avg_indoor IS NOT NULL AND v_avg_setting IS NOT NULL THEN
            IF para_target_mode = 'Cooling'
               AND v_avg_indoor - v_avg_setting > 2.0 THEN
                v_setpoint_flag := true;
            ELSIF para_target_mode = 'Heating'
               AND v_avg_setting - v_avg_indoor > 2.0 THEN
                v_setpoint_flag := true;
            END IF;
        END IF;

        v_carnot_cop := NULL;
        IF v_avg_indoor IS NOT NULL
           AND v_avg_outdoor IS NOT NULL
           AND v_avg_outdoor > v_avg_indoor THEN
            v_carnot_cop := (v_avg_indoor + 273.15)
                            / (v_avg_outdoor - v_avg_indoor);
        END IF;

        IF COALESCE(v_capacity_ratio < 0.85, false)
           OR COALESCE(v_actual_efficiency < para_eer_threshold, false)
           OR (v_carnot_cop IS NOT NULL
               AND v_actual_cop IS NOT NULL
               AND COALESCE(v_actual_cop < 0.04 * v_carnot_cop, false))
           OR v_setpoint_flag THEN
            -- affected row
        ELSE
            CONTINUE;
        END IF;

        IF COALESCE(v_capacity_ratio > 0, false) THEN
            v_energy_multiplier := 1.0 / v_capacity_ratio;
        ELSE
            v_energy_multiplier := 1.0;
        END IF;

        UPDATE energy_consumption
           SET energy_consumption_kwh = energy_consumption_kwh * v_energy_multiplier
         WHERE ac_id = r.ac_id
           AND mode = para_target_mode;

        IF COALESCE(v_capacity_ratio < 0.85, false) THEN
            UPDATE air_conditioner_info
               SET power_consumption_watts =
                       power_consumption_watts
                       * LEAST(1.5, 1.0 + (1.0 - v_capacity_ratio))
             WHERE ac_id = r.ac_id;
        END IF;

        IF v_sample_days > 0 THEN
            v_annual_emissions := (v_total_consumption / v_sample_days)
                                  * 365.0 * 0.000233;
        ELSE
            v_annual_emissions := v_original_power_watts / 1000.0
                                  * 1000.0 * 0.000233;
        END IF;

        INSERT INTO carbon_emissions
            (id, emission_factor, annual_emissions_tonnes)
        VALUES
            (next_id, 0.000233, v_annual_emissions);

        next_id := next_id + 1;
    END LOOP;
END;
$$;
